insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_goal_oriented','goal-oriented','adjective','focused on achieving clear aims or results','[{"senseId":"goal_oriented_1","meaning":"focused on achieving clear aims or results","acceptedParaphrases":["focused on goals","aim-driven"],"masteryContexts":[{"contextId":"u1_21_goal_oriented_meaning","text":"The manager is goal-oriented: she cares less about how a task is done than about reaching the agreed result by Friday.","meaning":"strongly focused on specific results"},{"contextId":"u1_21_goal_oriented_paraphrase","text":"A goal-oriented runner writes a target time for each race and trains only in ways that will help reach it.","meaning":"directed toward achieving clear aims"}],"contextDependentParaphrases":[],"misleadingDistractors":["easily distracted","casual","unplanned"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_achievement','achievement','noun','something important or difficult that has been successfully completed','[{"senseId":"achievement_1","meaning":"something important or difficult that has been successfully completed","acceptedParaphrases":["accomplishment","success"],"masteryContexts":[{"contextId":"u1_22_achievement_meaning","text":"Finishing the marathon in under four hours was a major achievement for someone who had only started running a year ago.","meaning":"worthwhile result gained through effort"},{"contextId":"u1_22_achievement_paraphrase","text":"The coach called her place on the national team the most difficult achievement of her career, because no one from the school had ever done it before.","meaning":"difficult success that has been completed"}],"contextDependentParaphrases":[],"misleadingDistractors":["attempt","problem","routine"]}]'::jsonb,'["achieve","achievable"]'::jsonb,'["major achievement","sense of achievement"]'::jsonb,'live'),
('vocab_elite','elite','adjective','belonging to the highest level of ability or performance','[{"senseId":"elite_1","meaning":"belonging to the highest level of ability or performance","acceptedParaphrases":["top-level","highest-level"],"masteryContexts":[{"contextId":"u1_23_elite_meaning","text":"The elite squad is closed to all but the top one per cent of players in the country, chosen purely on results.","meaning":"among the highest performers"},{"contextId":"u1_23_elite_paraphrase","text":"Entry to the elite competition is restricted to the top ten ranked players in the country, so most club players never qualify.","meaning":"at the top level of ability"}],"contextDependentParaphrases":[],"misleadingDistractors":["average","beginner","local"]}]'::jsonb,'[]'::jsonb,'["elite athlete","elite level"]'::jsonb,'live'),
('vocab_overwhelming','overwhelming','adjective','so strong or great that it is difficult to manage or resist','[{"senseId":"overwhelming_1","meaning":"so strong or great that it is difficult to manage or resist","acceptedParaphrases":["very powerful","extremely strong"],"masteryContexts":[{"contextId":"u1_24_overwhelming_meaning","text":"The support from the home crowd was so overwhelming that the young players could hardly think or hear their coach.","meaning":"too powerful to manage easily"},{"contextId":"u1_24_overwhelming_paraphrase","text":"Voters gave the new mayor an overwhelming majority, with more than ninety per cent supporting her.","meaning":"greater than can be comfortably handled"}],"contextDependentParaphrases":[],"misleadingDistractors":["minor","manageable","ordinary"]}]'::jsonb,'["overwhelm","overwhelmed"]'::jsonb,'[]'::jsonb,'live'),
('vocab_generation','generation','noun','a group of people born and living at roughly the same time','[{"senseId":"generation_1","meaning":"a group of people born and living at roughly the same time","acceptedParaphrases":["age group","people of the same era"],"masteryContexts":[{"contextId":"u1_25_generation_meaning","text":"People born in the nineties are often described as part of the same generation, because they grew up with similar technology.","meaning":"people from roughly the same age period"},{"contextId":"u1_25_generation_paraphrase","text":"A new generation of players, all born after the year 2005, is replacing the champions who dominated the sport for years.","meaning":"group born during a similar era"}],"contextDependentParaphrases":[],"misleadingDistractors":["team","audience","committee"],"teacherNote":"Use the age-group sense here."}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_challenge','challenge','noun','a difficult task or situation that tests ability','[{"senseId":"challenge_1","meaning":"a difficult task or situation that tests ability","acceptedParaphrases":["difficult task","test"],"masteryContexts":[{"contextId":"u1_26_challenge_meaning","text":"The coach set the squad a challenge: to run ten kilometres without stopping, to see who could push their limits.","meaning":"difficulty that tests someone’s ability"},{"contextId":"u1_26_challenge_paraphrase","text":"Playing the champions away from home will be a serious challenge for our young team, but we are ready to try.","meaning":"demanding problem requiring skill or effort"}],"contextDependentParaphrases":[],"misleadingDistractors":["reward","solution","routine"]}]'::jsonb,'["challenging","challenger"]'::jsonb,'["face a challenge","major challenge"]'::jsonb,'live'),
('vocab_solution','solution','noun','an answer to a problem or a way of dealing with a difficulty','[{"senseId":"solution_1","meaning":"an answer to a problem or a way of dealing with a difficulty","acceptedParaphrases":["answer","way to solve a problem"],"masteryContexts":[{"contextId":"u1_27_solution_meaning","text":"The club finally found a solution that ended the shortage of training space: it shared the school gym.","meaning":"method that resolves a difficulty"},{"contextId":"u1_27_solution_paraphrase","text":"One practical solution to the noise problem is to move the matches to the afternoon.","meaning":"workable way to fix a problem"}],"contextDependentParaphrases":[],"misleadingDistractors":["cause","argument","challenge"]}]'::jsonb,'["solve","solvable"]'::jsonb,'["find a solution","practical solution"]'::jsonb,'live'),
('vocab_pastime','pastime','noun','an activity done regularly for enjoyment in your free time','[{"senseId":"pastime_1","meaning":"an activity done regularly for enjoyment in your free time","acceptedParaphrases":["hobby","leisure activity"],"masteryContexts":[{"contextId":"u1_28_pastime_meaning","text":"Collecting old coins is a popular pastime among retired people, who enjoy it in the afternoons.","meaning":"enjoyable activity done outside work"},{"contextId":"u1_28_pastime_paraphrase","text":"For many teenagers, playing video games is a favourite pastime, not a way of earning money.","meaning":"recreational pursuit for spare hours"}],"contextDependentParaphrases":[],"misleadingDistractors":["career","duty","competition"]}]'::jsonb,'[]'::jsonb,'["popular pastime"]'::jsonb,'live'),
('vocab_feat','feat','noun','an impressive achievement that requires skill, strength, or courage','[{"senseId":"feat_1","meaning":"an impressive achievement that requires skill, strength, or courage","acceptedParaphrases":["remarkable achievement","impressive accomplishment"],"masteryContexts":[{"contextId":"u1_29_feat_meaning","text":"After two years of daily training, she completed the mountain run in under an hour, a feat that she had earned through practice rather than chance.","meaning":"notable act requiring unusual skill"},{"contextId":"u1_29_feat_paraphrase","text":"Finishing the race with a broken ankle was a feat that earned the runner a standing ovation from the whole stadium.","meaning":"impressive accomplishment that is difficult"}],"contextDependentParaphrases":[],"misleadingDistractors":["mistake","routine","attempt"]}]'::jsonb,'[]'::jsonb,'["remarkable feat"]'::jsonb,'live'),
('vocab_regardless','regardless','adverb','without being affected by a particular fact or situation','[{"senseId":"regardless_1","meaning":"without being affected by a particular fact or situation","acceptedParaphrases":["despite this","in any case"],"masteryContexts":[{"contextId":"u1_30_regardless_meaning","text":"The match will take place regardless of the weather, so bring waterproof clothes just in case.","meaning":"without letting that fact change things"},{"contextId":"u1_30_regardless_paraphrase","text":"Every student must attend training, regardless of their ability or experience, so beginners and the best players train together.","meaning":"despite the stated circumstance"}],"contextDependentParaphrases":[],"misleadingDistractors":["because of this","only if","as a result"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live')
